               ['Ch.2 tr.30', T('Nhãn "η th,Otto" trên công thức Diesel', 'Label "η th,Otto" on the Diesel formula'), T('phải là th,Diesel (nội dung đúng: 1 − q_out/(k·q_in))', 'should read th,Diesel (the content is right: 1 − q_out/(k·q_in))')],
