                ['14', T('giả thiết không khí-chuẩn', 'air-standard assumptions'), '§9-3 (tr.492)', '—', '—'],
                ['15–18', T('động cơ piston: r, MEP, SI/CI', 'reciprocating engines: r, MEP, SI/CI'), '§9-4 (tr.493–494)', '—', '—'],
                ['19–25', T('chu trình Otto', 'Otto cycle'), '§9-5 (tr.494–499)', '—', '—'],
                ['26–32', T('chu trình Diesel', 'Diesel cycle'), '§9-6 (tr.500–502)', '—', '—'],
                ['33–40', T('Brayton, r_p tối ưu', 'Brayton, optimum r_p'), '§9-8 (tr.507–514)', '§4.3.1 (tr.152–195)', '§4.2.3 (tr.207)'],
